/**
 * THE TOOL SHEET
 *
 * Six painted tools in a 3x2 grid, sliced by index. Same reasoning as the
 * ingredients: one picture is consistent by construction, where six separately
 * drawn ones never match each other.
 *
 * The supplied sheet is drawn on a cream ground with a printed border round each
 * cell. Both are keyed out here at build time — a flood fill from the cell edges,
 * plus a seed inside the press frame, which is the one enclosed region the fill
 * cannot reach from outside. Keying is possible at all because these are drawn
 * with hard contour lines; it would not work on a soft-edged painting.
 *
 * ORDER IS LOAD-BEARING and matches ApplianceId below.
 */
export const TOOL_COLS = 3;
export const TOOL_ROWS = 2;
export const TOOL_CELL_W = 210;
export const TOOL_CELL_H = 212;
export const TOOL_SHEET_W = 631;
export const TOOL_SHEET_H = 424;

/** Cell index per tool. r1: fan, mister, press. r2: centrifuge, agitator, paddle. */
export const TOOL_INDEX: Record<string, number> = {
  portable_fan: 0,
  humidifier:   1,
  wooden_press: 2,
  centrifuge:   3,
  agitator:     4,
  mash_paddle:  5,
};

export const TOOL_SHEET = "data:image/png;base64,";
